use super::KernelRule;

#[allow(clippy::too_many_lines)]
pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── D: dispatch/admission correctness (#30100) — the fused
        // MUL_MAT+ADD residual picker mispicks when both ADD operands
        // are mat-mul outputs; identity, not negation.
        KernelRule {
            rule_id: "fusion-residual-selected-by-identity-not-negation".to_string(),
            gpu_concept: "MECHANISM (the fused-op residual picker, the mispick face; category D — dispatch/admission correctness): when a fusion admission (or any graph rewrite consuming one operand of a binary op) must pick WHICH operand is the residual, select by BUFFER/TENSOR IDENTITY against the op just fused — never by a NEGATED op-class predicate (the operand whose op is not X): the negation is sound only while at most one operand can match X, and a chain (x = W1 @ u + W2 @ v) violates exactly that — and when the fused op sits at the ADD's src[1], the mispick resolves to the fused matmul's OWN output, a buffer the fusion never writes, so the kernel adds whatever that slot holds. THE SOURCE LAW, verbatim (commit message): 'ggml_metal_op_mul_mat_mma picks the residual of a fused MUL_MAT+ADD as the ADD operand whose op is not MUL_MAT. When both operands of the ADD are mat-mul outputs (x = W1 @ u + W2 @ v), that test is true for both, so the residual resolves to the fused mat-mul's own, never-written output and the kernel adds whatever that buffer holds.' AND: 'The fusion check (ggml_metal_mul_mat_add_operand) already selects the operand by identity; make the encoder do the same.' THE ONE-LINE REPAIR, verbatim (ggml-metal-ops.cpp:2479 removed, :2480-2481 added): 'res = dst->src[0]->op == GGML_OP_MUL_MAT ? dst->src[1] : dst->src[0];' became '// the residual is the other operand of the ADD, by identity: it can itself be a MUL_MAT output' + 'res = dst->src[0] == op ? dst->src[1] : dst->src[0];' — a POINTER compare against the fused op, not an op-predicate on a src slot. THE FAILURE SHAPE, verbatim (commit message): 'Clef decision models hit this in their head (proj_option_context @ ctx + proj_option_lexical @ lex, 9 option rows): on Metal, /v1/systemone probabilities collapse toward uniform (billing 0.28 where the CPU backend gives 0.977, Cloudflare_clef-flash Q8_0), deterministic per memory layout, correct with GGML_METAL_FUSION_DISABLE=1. Not a quantization issue: the same file is right on CPU.' — five signatures: SILENT (the add reads a never-written buffer; no error anywhere, probabilities just wrong), BACKEND-LOCAL (Metal only; the same file right on CPU), DETERMINISTIC PER MEMORY LAYOUT (reproducible, which is why it reads as a model bug rather than a race), KILL-SWITCH-FLIPPING (GGML_METAL_FUSION_DISABLE=1 makes it correct — proof the FUSION ADMISSION is the defect, not the model or the quant), DISCOVERED IN PRODUCTION (a served decision endpoint collapsing toward uniform, 0.28 vs 0.977). THE TEST THAT FORCES THE CLASS, verbatim: 'Add a MUL_MAT_ADD mode to test-backend-ops where the residual is a second mat-mul; on Metal it fails 27 of 28 cases before this change (the one pass is f16 n=2, under the MMA row threshold, so nothing fuses).' — the mode enum at tests/test-backend-ops.cpp:7236 ('MUL_MAT_ADD_MM_MM, // mm2 + mm: the residual is itself a mat-mul output, so both operands are MUL_MAT'), the graph arm at :7292-7297 building exactly the chain (a2 = ggml_new_tensor_2d(ctx, type_a, k, m); mm2 = ggml_mul_mat(ctx, a2, b); out = ggml_add(ctx, mm2, mm)). DECISION CONTENT: (1) any operand-picking predicate inside a fusion or graph rewrite must be decided by IDENTITY against the fused producer (src[0] == op ? src[1] : src[0]) — an op-class test on one slot silently assumes the fused op's POSITION in the src array, which the graph does not promise; (2) a negated predicate (not-X) is sound ONLY under an at-most-one-match premise — if chains are representable in the graph (they are ordinary), the premise is unmet and the predicate must be replaced, not commented; (3) the residual of a fused binary op IS the operand that is not the producer — an identity question; the admission one layer up (ggml_metal_mul_mat_add_operand) already selected by identity, and the repair makes the encoder agree with its own admission; (4) the regression test must CONSTRUCT the violating shape (both operands match X) or it passes vacuously — the one pre-fix pass was f16 n=2, under the MMA row threshold, so nothing fused and the fusion path was never exercised. REGIME: fusion admissions and graph rewrites that choose one operand of a binary op (fused MUL_MAT+ADD, residual adds, scale-and-add epilogues); backend-local fast paths behind kill switches (the kill-switch flip is the cheapest A/B this failure class admits). ANTI-REGIME: an op-class predicate as an ADMISSION filter (may this pair fuse at all) is fine — the rule fires only when the predicate also SELECTS the operand; a graph with a proven at-most-one-match invariant is the old form's sound zone — but chains are ordinary graphs, so treat the premise as unmet. NotBenchable here (correctness rule — the evidence class is a reproduced silent-wrong-answer plus a 27-of-28 failing test mode, not a timing figure). KINSHIP (do not double-count): bit-exact-dispatch-fusion-boundary-emulation (B97) is the fusion-correctness family head — its axis is ROUNDING-BOUNDARY emulation under a bit-identity contract, THIS is OPERAND SELECTION inside the fusion admission (a mispick yields stale-buffer garbage, not different roundings); fusion-payback-gated-on-per-dispatch-overhead owns the fusion ECONOMICS (whether to fuse at all); fuse-residual-via-in-place-output-array owns the in-place ALIAS mechanism that makes the fused add's output writable — this rule picks WHICH tensor the fused kernel treats as the residual; deferred-residual-fused-into-next-layer-norm (B63) owns the cross-iteration SCHEDULING of a residual, not its operand identity; mask-sentinel-matches-reduction-identity owns the uninitialized-slot hazard on a different surface (a masked lane must WRITE the reduction's identity; here the defect is WHICH operand the rewrite reads). Corpus greps (over src/domains/kernel_opt/corpus/): negat* — sign-negation senses only (gfni branch-free negate, env-polarity migration); identity — descriptor-write memos (descriptor-set-binding-memo-destroy-epoch) and cache keys, no operand selection; uninitialized — the identity-element rule + role-scoped stores (B118), neither a selection; ADD operand — zero. CITE: ggml-org/llama.cpp @ 7e8324f5feba1d8be3f966e1791e84107e40cdd7 (#30100, MIT) -- ggml/src/ggml-metal/ggml-metal-ops.cpp:2479 (the removed negated-predicate line) + :2480-2481 (the identity comment + the identity compare), tests/test-backend-ops.cpp:7236 (the MUL_MAT_ADD_MM_MM enum + comment) + :7247 (the mm2+mm case label) + :7292-7297 (the two-matmul graph arm) + :10420 (the mode loop admits it), commit message (the failure report + the 27-of-28 datum). Batch 208 / Plan 208.".to_string(),
            ref_shape: "// naive: the fused MUL_MAT+ADD residual is picked by an OP-CLASS\n// NEGATION — the ADD operand whose op is not MUL_MAT, tested on\n// src[0] alone. Sound only while at most one operand can match; the\n// chain shape (x = W1 @ u + W2 @ v) makes BOTH match, and when the\n// fused matmul sits at src[1] the pick resolves to src[1] — the\n// fused matmul's OWN output, never written before the add reads it.\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum Op {\n    MulMat,\n    Add,\n}\n\nstruct Node {\n    op: Op,\n    /// What the buffer holds when the ADD kernel reads it. The fused\n    /// matmul's own output slot is NEVER WRITTEN (the fusion redirected\n    /// the matmul's stores into the add), so it holds stale bytes —\n    /// deterministic per memory layout, different per backend.\n    holds: &'static str,\n}\n\n// ggml-metal-ops.cpp:2479, the REMOVED line:\n//   res = dst->src[0]->op == GGML_OP_MUL_MAT ? dst->src[1] : dst->src[0];\nfn residual_naive(dst_src: [usize; 2], nodes: &[Node]) -> usize {\n    if nodes[dst_src[0]].op == Op::MulMat {\n        dst_src[1] // both operands MulMat: lands on the fused op at [1]\n    } else {\n        dst_src[0]\n    }\n}\n\n#[test]\nfn the_negated_predicate_mispicks_the_chain() {\n    // x = W2 @ v + W1 @ u spelled add(mm2, mm): the fused matmul `mm`\n    // is src[1]; src[0] is the OTHER mat-mul output mm2.\n    let mm2 = Node { op: Op::MulMat, holds: \"mm2 output (fresh)\" };\n    let mm = Node { op: Op::MulMat, holds: \"stale bytes (never written)\" };\n    let nodes = vec![mm2, mm]; // dst->src = [mm2, mm]\n    let res = residual_naive([0, 1], &nodes);\n    assert_eq!(res, 1); // the FUSED op's own buffer\n    assert_eq!(nodes[res].holds, \"stale bytes (never written)\");\n    // the add computes out = mm2 + <whatever that slot holds> — silent.\n}".to_string(),
            opt_pattern: "// optimized: the residual is picked by POINTER IDENTITY against the\n// op the fusion fused — if the ADD's first operand IS the fused\n// matmul, the residual is the second operand, else the first. The\n// other operand's op class never enters the test, so a chain (both\n// operands MUL_MAT) cannot flip the pick.\n//   // the residual is the other operand of the ADD, by identity: it\n//   // can itself be a MUL_MAT output\n//   res = dst->src[0] == op ? dst->src[1] : dst->src[0];\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum Op {\n    MulMat,\n    Add,\n}\n\nstruct Node {\n    op: Op,\n    holds: &'static str,\n}\n\n// ggml-metal-ops.cpp:2480-2481, the ADDED line: identity against the\n// fused op, never a negated op-class predicate.\nfn residual_identity(dst_src: [usize; 2], fused: usize) -> usize {\n    if dst_src[0] == fused {\n        dst_src[1]\n    } else {\n        dst_src[0]\n    }\n}\n\n// the forcing mode (tests/test-backend-ops.cpp:7236 + :7292-7297):\n//   MUL_MAT_ADD_MM_MM, // mm2 + mm: the residual is itself a mat-mul\n//                      // output, so both operands are MUL_MAT\n//   ggml_tensor * a2  = ggml_new_tensor_2d(ctx, type_a, k, m);\n//   ggml_tensor * mm2 = ggml_mul_mat(ctx, a2, b);\n//   out = ggml_add(ctx, mm2, mm);\nfn chain_graph(fused_mm: usize, other_mm: usize) -> [usize; 2] {\n    [other_mm, fused_mm] // add(mm2, mm): both operands are MUL_MAT\n}\n\n#[test]\nfn identity_picks_the_other_operand_under_a_chain() {\n    // the same graph the naive form mispicked: the fused mm at src[1].\n    assert_eq!(residual_identity(chain_graph(1, 0), 1), 0);\n    // and the plain shape is unchanged: fused mm at src[0] -> src[1].\n    assert_eq!(residual_identity(chain_graph(0, 1), 0), 1);\n    // the 27-of-28 datum: the single pre-fix pass was f16 n=2, under\n    // the MMA row threshold — nothing fused, so the fusion path (and\n    // the mispick) was never exercised there. The mode exists to force\n    // the chain through the fusion admission.\n}\n\n#[test]\nfn the_rewrite_is_a_strict_generalization() {\n    // a non-MUL_MAT residual (the old form's only sound case) picks\n    // identically — identity never flips a pick the negation got right:\n    assert_eq!(residual_identity([0, 1], 0), 1);\n    assert_eq!(residual_identity([0, 1], 2), 0); // neither operand fused\n}".to_string(),
        },

        // ── D: dispatch admission + aliasing conditions (#29171) — the
        // MKL FA exact-shape MLA admission + the V-as-strided-view
        // conjuncts; carries the landed-then-reverted F16-scores watch.
        KernelRule {
            rule_id: "fa-fast-path-validated-exact-shape-admission-v-as-strided-view".to_string(),
            gpu_concept: "MECHANISM (exact-shape validated admission + the V-as-strided-view conjuncts; category D — dispatch admission + aliasing conditions): a flash-attention fast-path gate requiring HOMOGENEOUS K/V widths and a head-dim cap silently excludes MLA-class shapes (K != V widths) to the slow TILE fallback — and the widening is done by EXACT-SHAPE VALIDATED ADMISSION, an allowlist conjunct naming the measured-good shape IN FULL, never a relaxation of the homogeneous predicate — paired with the three VIEW conditions the admitted shape's cache layout imposes: descriptor mode from the ACTUAL row stride, a stride exception pinned to the full (shape AND identity AND real-view AND shared-stride) triple, and dequant aliasing gated on LOGICAL width equality, never view identity alone. THE SOURCE LAW, verbatim (commit message): 'GLM-4.7 Flash uses an MLA shape with 576-wide Q/K heads, a 512-wide V head, GQA 20, and F16 KV. The SYCL dispatcher rejects this shape because the normal MKL flash-attention gate requires matching K/V widths and caps the head dimension at 512, so prompt processing falls back to the substantially slower TILE kernel.' AND: 'Admit only the validated 576/576/512, GQA-20 F16 shape to the existing MKL pipeline. Keep all other mismatched K/V shapes on their current fallback paths.' THE ADMISSION, verbatim (fattn.cpp:149-157): 'const bool standard_shape = Q->ne[0] >= 64 && Q->ne[0] <= 512 && Q->ne[0] % 64 == 0 && Q->ne[0] == V->ne[0];' then '// GLM-4.7 Flash's MLA shape is already expressible by the MKL pipeline: KQ GEMM uses DKQ=576 while VKQ and output use DV=512. Keep this narrow until other mismatched K/V shapes have independent correctness data.' then 'const bool glm_mla_shape = Q->ne[0] == 576 && K->ne[0] == 576 && V->ne[0] == 512 && gqa_ratio == 20 && K->type == GGML_TYPE_F16 && V->type == GGML_TYPE_F16;' — admitted as '(standard_shape || glm_mla_shape)' (:158-159). THE VIEW HALF, three conjuncts: (a) fattn-mkl.cpp:285-288, verbatim comment '// MLA's V cache is a 512-wide view of 576-wide K rows. Treat any padded row stride as strided even when there is only one KV head.' — the F16 descriptor mode generalizes from interleaved to 'interleaved || d.nb1 != d.D * (int64_t)sizeof(sycl::half)' (the padded-row-stride check) selecting MKL_FA_KV_MODE_F16_INTERLEAVED; (b) fattn.cpp:169-172, the stride exception is a TRIPLE — 'const bool glm_v_stride = glm_mla_shape && t == V && V->view_src && V->nb[1] == K->nb[1];' (the admitted shape AND identity-to-V AND a real view AND K's own row stride), guarding the kv_strides_ok loop that would otherwise reject any padded F16 row stride; (c) fattn-mkl.cpp:417-421, verbatim comment '// Alias the dequantized buffers only when K and V expose the same values. MLA V is a narrower view of K and needs its own strided dequantization.' — 'const bool V_is_K_view = V->ne[0] == K->ne[0] && V->view_src && ...': the LOGICAL-WIDTH conjunct ADDED on top of view identity. MEASURED (source-reported, Intel Arc Pro B70 at master e613ef2): 'pp8192 improves from 432.80 to 1292.29 tok/s (2.99x, +198.6%). tg256 remains unchanged within noise at 45.67 versus 45.65 tok/s.' THE IN-COMMIT NEGATIVE (record as watch): the F16-scores sub-commit (store MKL flash attention scores in F16 — 'The F32 score matrix is the largest flash-attention intermediate on this path; storing it as F16 halves its size and traffic' — measured pp8192 +4.6%, pp64000 +12.2%, pp131072 +13.5%) was REVERTED in the same merged PR (a revert commit reverting 265f9748164dc88e02678425b75f520ccd528b32) with the revert reason UNSTATED: measured-positive on record, landed-reverted — never adopt without the revert reason. DECISION CONTENT: (1) widen a shape gate by ALLOWLIST, never by relaxation — the new conjunct names EVERY dim + the GQA ratio + BOTH dtypes of the one measured-good shape, and the narrowness is stated in-source ('Keep this narrow until other mismatched K/V shapes have independent correctness data.'); (2) check what actually blocks: the MKL pipeline was ALREADY capable ('already expressible': the KQ GEMM runs DKQ=576 while VKQ and output use DV=512) — the predicate was the only blocker, so the fix is admission-side with ZERO kernel changes; (3) a strided VIEW operand imposes conditions the dense path never asks: descriptor mode from the ACTUAL row stride (padded => strided, even at one KV head), any stride exception pinned to the full triple (three independent refusals — shape, identity+view, shared stride — each of which alone would over-admit), and buffer aliasing gated on LOGICAL width equality (a narrower view of the same rows is NOT the same values). REGIME: fast-path admissions in front of pipelines whose kernels already serve a wider shape space than the gate; models whose cache layout is a narrower strided view of a sibling tensor (MLA's V-of-K). ANTI-REGIME: relaxing the gate to any K != V shape (no independent correctness data — the in-source refusal); shapes the kernels genuinely cannot serve (the fallback stays); aliasing by view identity alone (a narrower view silently reads the wrong dequant); adopting the F16-scores watch (revert reason unstated). NotBenchable here (the 2.99x is source-reported on THEIR SYCL/Arc lane — provenance, never a bar; the decision content is the admission shape + the aliasing conjuncts). KINSHIP (do not double-count): sibling-kernel-admission-gap-absorbed-by-generalist (B205) — TWO kernels' predicates leaving a joint gap, absorbed by a complement-predicate CALL; THIS is ONE gate widened by a validated exact shape (no sibling predicate involved); tail-clamped-row-reuse-widens-fast-kernel-admission (B205) — the single-kernel unaligned-tail face via a compile-time partial variant; THIS widens by allowlisting a DIFFERENT shape family (no partial variant, no new instantiation); dispatcher-eligibility-predicate-lags-kernel-capability (B103, + its B204 pairing-migration orphan rider) — the nearest neighbor: a predicate narrower than the pipeline's real capability, silent slow fallback, no test fails; the delta is the FIX shape (there: DELETE the stale conjunct — the kernel always served the shape; here: the shape was expressible but had no independent correctness data, so the admission is an exact-shape allowlist with the narrowness stated in-source); vendor-batched-gemm-contiguity-staging (B77) — contiguity routing into a vendor library's internal paths, a different axis; the B170 rider on fuse-gate-up-gemv-activation — a strided VIEW consumed by a compiled kernel (the view-shape hazard on the CONSUMER side; THIS is the descriptor/aliasing conditions on the ADMISSION side); strided-view-offset-fit32-launch-proof (B195) — strided-view OFFSET-SAFETY proofs at launch, a different question; append-cache-rewind-overwrite-in-place (B39) — the in-corpus MLA-cache family (the rewind_mla_caches_to lane), family adjacency only. Corpus greps (over src/domains/kernel_opt/corpus/): allowlist — the sanitizer-env sense only (env-gate-reaches-and-arms-the-scored-process); DKQ — zero; strided view / strided-view — B77, the B170 rider, and B195 as above; MLA — the B39 cache rule, the vLLM fused_mla_key_concat rider, and mla_backward senses, none an FA admission; kv.view / V_is_K — zero. CITE: ggml-org/llama.cpp @ d2a79e60464903f9832fbecdba48bd4cc6c47e75 (#29171, MIT) -- ggml/src/ggml-sycl/fattn.cpp:149-157 (standard_shape + the GLM comment + glm_mla_shape) + :158-159 (the admission disjunction) + :169-172 (glm_v_stride + the guard), ggml/src/ggml-sycl/fattn-mkl.cpp:285-288 (the padded-stride comment + the strided-descriptor selection) + :417-421 (the aliasing comment + V_is_K_view with the width conjunct), commit message (the measured pair + the landed-then-reverted F16-scores sub-commit). Batch 208 / Plan 208.".to_string(),
            ref_shape: "// naive: the flash-attention fast path requires HOMOGENEOUS K/V\n// widths and caps the head dimension — an MLA shape (DKQ 576,\n// DV 512) fails the width-match conjunct and silently falls back to\n// the slow TILE kernel for prompt processing (fattn.cpp before\n// d2a79e6046).\nconst HEAD_DIM_MAX: usize = 512;\n\nstruct Shape {\n    q_dim: usize, // Q->ne[0]\n    k_dim: usize, // K->ne[0]\n    v_dim: usize, // V->ne[0]\n    gqa: u32,\n    k_f16: bool,\n    v_f16: bool,\n}\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum Kernel {\n    Mkl,\n    Tile,\n}\n\nfn route_naive(s: &Shape) -> Kernel {\n    // matching K/V widths + the 512 cap: a 576-wide head refuses here\n    let standard = s.q_dim >= 64\n        && s.q_dim <= HEAD_DIM_MAX\n        && s.q_dim % 64 == 0\n        && s.q_dim == s.v_dim;\n    if standard {\n        Kernel::Mkl\n    } else {\n        Kernel::Tile // GLM prompt processing lands HERE: ~3x slower\n    }\n}\n\n#[test]\nfn the_mla_shape_pays_the_tile_fallback() {\n    let glm = Shape { q_dim: 576, k_dim: 576, v_dim: 512, gqa: 20, k_f16: true, v_f16: true };\n    assert_eq!(route_naive(&glm), Kernel::Tile); // 432.80 vs 1292.29 tok/s\n    // the homogeneous envelope keeps working — the gate is not WRONG,\n    // it is narrower than the pipeline it fronts.\n    let std = Shape { q_dim: 512, k_dim: 512, v_dim: 512, gqa: 8, k_f16: true, v_f16: true };\n    assert_eq!(route_naive(&std), Kernel::Mkl);\n}".to_string(),
            opt_pattern: "// optimized: widen by EXACT-SHAPE VALIDATED ADMISSION — an allowlist\n// conjunct naming the measured-good shape in full, never a relaxation\n// of the homogeneous predicate — then serve the shape's VIEW\n// structure: V is a 512-wide strided view of 576-wide K rows, so the\n// descriptor treats any padded row stride as strided (even at one KV\n// head), the stride exception is a (shape AND identity AND real-view\n// AND shared-stride) triple, and dequant aliasing requires LOGICAL\n// width equality on top of view identity.\nconst HEAD_DIM_MAX: usize = 512;\nconst GLM_DKQ: usize = 576;\nconst GLM_DV: usize = 512;\nconst GLM_GQA: u32 = 20;\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nstruct Shape {\n    q_dim: usize,\n    k_dim: usize,\n    v_dim: usize,\n    gqa: u32,\n    k_f16: bool,\n    v_f16: bool,\n}\n\n// fattn.cpp:149-150, unchanged.\nfn standard_shape(s: &Shape) -> bool {\n    s.q_dim >= 64 && s.q_dim <= HEAD_DIM_MAX && s.q_dim % 64 == 0 && s.q_dim == s.v_dim\n}\n\n// fattn.cpp:154-156 — every dim, the GQA ratio and BOTH dtypes named\n// in full: 'Keep this narrow until other mismatched K/V shapes have\n// independent correctness data.'\nfn glm_mla_shape(s: &Shape) -> bool {\n    s.q_dim == GLM_DKQ\n        && s.k_dim == GLM_DKQ\n        && s.v_dim == GLM_DV\n        && s.gqa == GLM_GQA\n        && s.k_f16\n        && s.v_f16\n}\n\n// fattn.cpp:158-159: the ALLOWLIST disjunction, not a relaxation.\nfn mkl_fa_admits(s: &Shape) -> bool {\n    standard_shape(s) || glm_mla_shape(s)\n}\n\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum Kernel {\n    Mkl,\n    Tile,\n}\n\nfn route(s: &Shape) -> Kernel {\n    if mkl_fa_admits(s) {\n        Kernel::Mkl\n    } else {\n        Kernel::Tile\n    }\n}\n\n// fattn-mkl.cpp:285-288: any padded F16 row stride is STRIDED, even\n// at one KV head — MLA's V is a 512-wide view of 576-wide K rows.\n#[derive(Clone, Copy, PartialEq, Eq)]\nenum KvMode {\n    F16Dense,\n    F16Interleaved,\n}\n\nfn f16_kv_mode(interleaved: bool, nb1: usize, logical_width: usize) -> KvMode {\n    let dense_row_bytes = logical_width * 2; // d.D * sizeof(half)\n    if interleaved || nb1 != dense_row_bytes {\n        KvMode::F16Interleaved\n    } else {\n        KvMode::F16Dense\n    }\n}\n\n// fattn.cpp:169-172: the stride exception is a TRIPLE — the admitted\n// shape AND identity-to-V AND a real view AND K's own row stride.\nfn glm_v_stride(s: &Shape, t_is_v: bool, v_is_view: bool, v_nb1: usize, k_nb1: usize) -> bool {\n    glm_mla_shape(s) && t_is_v && v_is_view && v_nb1 == k_nb1\n}\n\n// fattn-mkl.cpp:417-421: alias the dequantized buffers only when K\n// and V expose the same values — LOGICAL width equality ON TOP of\n// view identity; a narrower view needs its own strided dequant.\nfn v_is_k_view(v_dim: usize, k_dim: usize, v_view_src_is_k: bool) -> bool {\n    v_dim == k_dim && v_view_src_is_k\n}\n\nfn glm() -> Shape {\n    Shape { q_dim: 576, k_dim: 576, v_dim: 512, gqa: 20, k_f16: true, v_f16: true }\n}\n\n#[test]\nfn the_exact_shape_is_admitted_and_narrowness_holds() {\n    assert_eq!(route(&glm()), Kernel::Mkl); // pp8192 432.80 -> 1292.29 tok/s\n    // the allowlist is NARROW: a mismatched shape WITHOUT the measured\n    // correctness data stays on its fallback (relaxation refused):\n    let other = Shape { v_dim: 256, ..glm() };\n    assert_eq!(route(&other), Kernel::Tile);\n    // ...and so does the right shape failing one conjunct:\n    let wrong_gqa = Shape { gqa: 8, ..glm() };\n    assert_eq!(route(&wrong_gqa), Kernel::Tile);\n}\n\n#[test]\nfn the_view_conditions_hold_as_triples_and_width_gates() {\n    let g = glm();\n    // V's padded row stride (576-wide rows, 512-wide logical) selects\n    // the strided descriptor even with no interleaving flag:\n    assert_eq!(f16_kv_mode(false, 576 * 2, 512), KvMode::F16Interleaved);\n    assert_eq!(f16_kv_mode(false, 512 * 2, 512), KvMode::F16Dense); // dense rows\n    // the stride exception holds only on the full triple — each\n    // conjunct alone refuses:\n    assert!(glm_v_stride(&g, true, true, 576 * 2, 576 * 2));\n    let other = Shape { v_dim: 256, ..g };\n    assert!(!glm_v_stride(&other, true, true, 576 * 2, 576 * 2)); // shape off\n    assert!(!glm_v_stride(&g, false, true, 576 * 2, 576 * 2)); // not V\n    assert!(!glm_v_stride(&g, true, false, 576 * 2, 576 * 2)); // not a view\n    assert!(!glm_v_stride(&g, true, true, 512 * 2, 576 * 2)); // stride differs\n    // aliasing needs LOGICAL width equality, not just view identity:\n    assert!(!v_is_k_view(512, 576, true)); // MLA's narrower V: own dequant\n    assert!(v_is_k_view(576, 576, true)); // same-width view: alias OK\n}".to_string(),
        },

        // ── D: graph construction (#29928) — the headless NextN/MTP
        // forward persists only through its cache writes; crop landed
        // over prune on pattern consistency, both depths measured.
        KernelRule {
            rule_id: "headless-draft-forward-crops-to-output-rows-cache-writes-persist".to_string(),
            gpu_concept: "MECHANISM (the zero-output-row draft forward, the cache-writes-persist contract; category D — graph construction): a draft/catch-up (MTP/NextN) forward issued with ZERO output rows persists ONLY through its cache writes (MLA latent, indexer key|gate, pooled-key) — everything consumer-side (the query path, the indexer selection, the attention body, the FFN, the LM head) is dead compute the graph builder must not schedule: not waste-per-row but waste-per-FORWARD, paid on every catch-up step the draft loop runs. THE SOURCE LAW (the deeper PRUNE arm), verbatim (commit message): 'A NextN forward with no output rows (the MTP catch-up and the draft-context prefill) persists only through its cache writes, so the headless graph keeps the MLA latent, indexer key|gate and pooled-key writes and drops the query path, the indexer selection, the attention body, the FFN and the LM head. The 4-token catch-up falls from 6.9 ms to 0.33 ms of kernels; the greedy output hashes and the draft acceptance are unchanged.' THE LANDED FINAL STATE (the CROP arm), verbatim: 'Replace the headless NextN prune with the crop pattern the other MTP graphs use: gather the attention output and the block input at the output ids before the position-wise FFN and the shared head. A NextN forward with no output rows (the MTP catch-up and the draft-context prefill) then runs the FFN and the head over zero rows. The 4-token catch-up falls from 6.9 ms to 2.9 ms of kernels; greedy output hashes are unchanged.' TWO ELIMINATION DEPTHS, MEASURED IN-COMMIT ON BOTH SIDES: deep PRUNE (drop the ops entirely — 6.9 → 0.33 ms, ~21x) vs CROP (gather at the output ids before the position-wise tail so the FFN and head run over zero rows — 6.9 → 2.9 ms, ~2.4x); the CROP LANDED for pattern consistency with the other MTP graphs despite the prune being ~8.8x faster on this cell — record the tradeoff honestly: consistency-of-pattern beat the deeper win, AND the prune's guard needed an extra correctness conjunct the crop structurally avoids (verbatim, the review fixes: 'The headless graph prune now also requires that no unmasked nextn extraction is live, because that mode reads n_tokens hidden rows regardless of the logits flags. Masked extraction publishes the hidden rows gathered by the output ids, so a batch whose output flags are not a prefix exports the right rows.'). CORRECTNESS PINS on both arms: greedy output hashes AND draft acceptance unchanged; a batch whose output flags are NOT A PREFIX must still export the right rows — masked extraction publishes the GATHERED hidden rows (res->t_h_nextn is set from the pre-crop tensor at glm5-next.cpp:657-659, then the shared head consumes the narrowed rows at :661-663). THE GUARD RIDE-ALONG (same commit), verbatim: 'A partial recurrent rollback whose tail cell is shared with another sequence is now rejected instead of silently moving that sequence's tail.' — llama-memory-recurrent.cpp:202-205: '// a cell shared by several sequences cannot move back for only one of them' + 'if (cell.seq_id.size() > 1) { return false; }'. THE SHARED-PATTERN SHAPE (commit, verbatim): 'Replace the local crop condition and the masked select of t_h_nextn with crop_before_nextn and crop_after_nextn, so the MTP graph narrows its rows the same way as the main graph and the other models.' — the MTP graph reuses the trunk's builders through a no_build tag ctor (models.h: build the helpers without the trunk, so graph_mtp can reuse them) and narrows with the SAME crop helpers — pattern reuse is a first-class property of the landed form. DECISION CONTENT: (1) the zero-output-row contract — a draft forward whose out-id set is empty persists through cache writes ONLY; the consumer side does not exist, so building it is dead compute on EVERY catch-up; (2) choose the elimination DEPTH deliberately and record the loser: prune (drop the ops) is deeper but needs a guard conjunct for every mode that reads hidden rows regardless of the logits flags — a real correctness complexity; crop (gather at the output ids before the position-wise tail) is pattern-consistent across graphs and structurally safe (zero rows in, zero rows out, the same code path as every output-bearing forward); (3) the crop gathers BOTH the position-wise input AND its residual branch (cur AND inpSA at :616-620, comment: narrow to the output tokens before the position-wise FFN; unmasked nextn embeddings need all rows) — cropping only one of the two changes the add; (4) the extraction contract: publish the GATHERED rows (masked extraction), never the full row set, so non-prefix output flags still export the right rows. REGIME: MTP/NextN/draft-model graph builders (catch-up passes, draft-context prefills); any headless forward whose persistence is state writes. ANTI-REGIME: a forward WITH output rows (the crop gathers at real ids; nothing to elide); the cache writes themselves (never dropped — they ARE the persistence); the trunk graph (the shared helpers serve it un-cropped); forcing the deeper prune where its guard conjuncts cannot be proven. NotBenchable here (both ms figures are source-reported on THEIR backend — provenance, never a bar; the decision content is the build shape + the guard contracts + the recorded depth tradeoff). KINSHIP (do not double-count): gdn-transition-replay-log-commit-many (the spec-decode commit family — journal + replay of ACCEPTED tokens after selection; THIS is the builder-side elision for the zero-consumer arm of the same pipeline); capture-break-count-not-perf-target — graph-construction economics (when restructuring beats forcing a count); device-side-argmax-minimal-download (B25) with its B129 MTP rider — the draft-selection READBACK half of the same MTP pass (one int32 crosses the bus); THIS is the draft FORWARD's build shape (a different axis); deferred-residual-fused-into-next-layer-norm (B63) — the general skip-what-no-consumer-reads instinct at the iteration-scheduling level (the consumer exists, one iteration later); THIS is its ZERO-CONSUMER face — the consumer side of a headless forward does not exist at all. Adjacent family (own greps, cited not owned): lm-head-loss-positions-only (B37) gates the vocab head to loss-support positions INSIDE a live forward — a per-position subset of a consumer that exists, vs this whole-graph zero-row case; the PAD family (zero-pad-ragged-tail-additive-identity B186, pad-tail-to-fixed-tile B84) MANUFACTURES zero rows so a tile can run — the inverse posture of zero rows meaning no consumer; write-before-read-state-skips-checkpoint owns WHAT to back up (the checkpoint set), not WHAT to build. Corpus greps (over src/domains/kernel_opt/corpus/): headless / nextn / catch-up / crop — zero owners; mtp — the B129 readback rider + the replay-commit family as above; zero rows — the pad family + a zero-row-alloc defect corollary (entries_gpu_06, an allocation floor-dividing to zero rows — a different defect); cache write — no owner. CITE: ggml-org/llama.cpp @ b9acf138a1e28ce1fc23b5a4fc4b12444b50f7ea (#29928, MIT) -- src/models/glm5-next.cpp:545-548 (the no_build helper ctor) + :550 (the graph_mtp ctor) + :616-620 (crop_before_nextn: the comment narrow to the output tokens before the position-wise FFN; unmasked nextn embeddings need all rows + the dual gather of cur and inpSA) + :657-659 (res->t_h_nextn published as the gathered hidden rows) + :661-663 (crop_after_nextn), src/llama-memory-recurrent.cpp:202-205 (the shared-tail rollback rejection), src/models/models.h:2744-2746 + :2796-2799 (the no_build + graph_mtp declarations); the crop helpers' definitions live in the shared builder base outside this diff. Batch 208 / Plan 208.".to_string(),
            ref_shape: "// naive: a NextN/MTP draft forward issued with ZERO output rows (the\n// MTP catch-up, the draft-context prefill) builds the FULL graph —\n// query path, indexer selection, attention body, FFN, LM head all\n// schedule — though nothing consumes their outputs: the forward\n// persists only through its cache writes. 6.9 ms of kernels for a\n// 4-token catch-up (source-reported).\n#[derive(Default)]\nstruct GraphBuilder {\n    ops: Vec<&'static str>,\n}\n\nimpl GraphBuilder {\n    fn build_full_headless(&mut self) {\n        self.cache_writes(); // the ONLY persistence\n        self.query_path(); // dead: no output rows read it\n        self.indexer_selection(); // dead\n        self.attention_body(); // dead\n        self.ffn(); // dead\n        self.lm_head(); // dead: the logits have no consumers\n    }\n\n    fn cache_writes(&mut self) {\n        // MLA latent + indexer key|gate + pooled-key writes\n        self.ops.push(\"cache_write\");\n    }\n    fn query_path(&mut self) {\n        self.ops.push(\"query\");\n    }\n    fn indexer_selection(&mut self) {\n        self.ops.push(\"indexer_sel\");\n    }\n    fn attention_body(&mut self) {\n        self.ops.push(\"attn\");\n    }\n    fn ffn(&mut self) {\n        self.ops.push(\"ffn\");\n    }\n    fn lm_head(&mut self) {\n        self.ops.push(\"lm_head\");\n    }\n}\n\n#[test]\nfn headless_full_graph_schedules_dead_compute() {\n    let mut g = GraphBuilder::default();\n    g.build_full_headless();\n    // six op classes for a forward whose only observable effect is\n    // the first one — 6.9 ms vs the 0.33 ms prune / 2.9 ms crop:\n    assert_eq!(g.ops.len(), 6);\n    assert_eq!(g.ops[0], \"cache_write\");\n}".to_string(),
            opt_pattern: "// optimized: the CROP (the landed arm) — keep the cache writes, run\n// the one DSA layer, then gather the attention output AND the block\n// input at the output ids BEFORE the position-wise FFN and the shared\n// head, so a zero-output-row forward runs the position-wise tail over\n// ZERO rows. (The deeper PRUNE arm — drop the ops entirely — measured\n// 6.9 -> 0.33 ms vs the crop's 6.9 -> 2.9 ms on the 4-token catch-up;\n// the crop landed for pattern consistency with the other MTP graphs,\n// and its guard avoids the prune's extra no-unmasked-extraction\n// conjunct.) The h_nextn rows are published GATHERED, so a batch\n// whose output flags are not a prefix still exports the right rows.\n#[derive(Default)]\nstruct GraphBuilder {\n    ops: Vec<&'static str>,\n    out_rows: usize,\n}\n\nimpl GraphBuilder {\n    fn build_cropped_headless(&mut self) {\n        self.cache_writes(); // the ONLY persistence\n        self.query_path(); // the one DSA layer's own compute\n        self.indexer_selection();\n        self.attention_body();\n        // crop_before_nextn(inp_out_ids) — glm5-next.cpp:616-620:\n        // 'narrow to the output tokens before the position-wise FFN;\n        // unmasked nextn embeddings need all rows'. BOTH branches are\n        // gathered (cur AND inpSA) or the add changes.\n        self.gather_at_output_ids();\n        self.ffn(); // over out_rows rows (zero on a catch-up)\n        // crop_after_nextn(inp_out_ids) — :661-663; h_nextn was already\n        // published as the gathered rows (:657-659).\n        self.gather_at_output_ids();\n        self.lm_head(); // over out_rows rows\n    }\n\n    fn cache_writes(&mut self) {\n        self.ops.push(\"cache_write\");\n    }\n    fn query_path(&mut self) {\n        self.ops.push(\"query\");\n    }\n    fn indexer_selection(&mut self) {\n        self.ops.push(\"indexer_sel\");\n    }\n    fn attention_body(&mut self) {\n        self.ops.push(\"attn\");\n    }\n    fn gather_at_output_ids(&mut self) {\n        // a ggml_get_rows at the output ids — empty when out_rows == 0\n        self.ops.push(if self.out_rows == 0 { \"gather:0rows\" } else { \"gather\" });\n    }\n    fn ffn(&mut self) {\n        self.ops.push(if self.out_rows == 0 { \"ffn:0rows\" } else { \"ffn\" });\n    }\n    fn lm_head(&mut self) {\n        self.ops.push(if self.out_rows == 0 { \"lm_head:0rows\" } else { \"lm_head\" });\n    }\n}\n\n#[test]\nfn headless_cropped_graph_runs_the_tail_over_zero_rows() {\n    let mut g = GraphBuilder { out_rows: 0, ..Default::default() };\n    g.build_cropped_headless();\n    // the same op CLASSES as the naive form (pattern consistency — the\n    // prune dropped four entirely) but the position-wise tail consumes\n    // zero rows: 6.9 -> 2.9 ms, greedy hashes unchanged.\n    assert_eq!(\n        g.ops,\n        vec![\n            \"cache_write\",\n            \"query\",\n            \"indexer_sel\",\n            \"attn\",\n            \"gather:0rows\",\n            \"ffn:0rows\",\n            \"gather:0rows\",\n            \"lm_head:0rows\",\n        ]\n    );\n}\n\n#[test]\nfn non_prefix_output_flags_still_export_the_right_rows() {\n    // masked extraction publishes the hidden rows GATHERED by the\n    // output ids (:657-659) — a batch whose flags are not a prefix\n    // exports exactly those rows, never the first n.\n    let hidden = vec![\"h0\", \"h1\", \"h2\", \"h3\"];\n    let out_ids = [0usize, 2, 3]; // NOT a prefix (1 is missing)\n    let exported: Vec<&str> = out_ids.iter().map(|&i| hidden[i]).collect();\n    assert_eq!(exported, vec![\"h0\", \"h2\", \"h3\"]);\n}\n\n#[test]\nfn shared_tail_rollback_is_rejected_not_moved() {\n    // llama-memory-recurrent.cpp:202-205: a partial rollback whose\n    // tail cell is shared with another sequence is rejected — moving\n    // it would silently move THAT sequence's tail.\n    fn partial_rollback_ok(cell_shared_by: usize) -> bool {\n        cell_shared_by <= 1 // upstream: if (cell.seq_id.size() > 1) return false;\n    }\n    assert!(!partial_rollback_ok(2));\n    assert!(partial_rollback_ok(1));\n}".to_string(),
        },
    ]
}
